xpath.script:
    (function() {
        // Price updates
        var currencySymbol = document.getElementById('currency_symbol').textContent;
        var currencyPosition = document.getElementById('currency_position').textContent;

        function formatMoney(amount) {
            var formatted = amount.toFixed(2);
            if (currencyPosition === 'before') {
                return currencySymbol + ' ' + formatted;
            } else {
                return formatted + ' ' + currencySymbol;
            }
        }

        function updateTotals() {
            var total = 0;
            var lines = document.querySelectorAll('tr.order-line');
            lines.forEach(function(tr) {
                var lineId = tr.dataset.lineId;
                var qty = parseFloat(document.getElementById('raw_qty_' + lineId).textContent) || 0;
                var priceInput = document.getElementById('price_input_' + lineId);
                var price;
                if (priceInput) {
                    price = parseFloat(priceInput.value) || 0;
                } else {
                    price = parseFloat(document.getElementById('raw_price_' + lineId).textContent) || 0;
                }
                var subtotal = qty * price;
                var subtotalSpan = document.getElementById('subtotal_' + lineId);
                if (subtotalSpan) {
                    subtotalSpan.innerHTML = formatMoney(subtotal);
                }
                total += subtotal;
            });
            document.getElementById('total_amount').innerHTML = formatMoney(total);
            document.getElementById('modal_total_amount').innerHTML = formatMoney(total);
        }

        // Increment and decrement functionality
        var priceInputs = document.querySelectorAll('.price-unit-input');
        var incrementButtons = document.querySelectorAll('.increment-btn');
        var decrementButtons = document.querySelectorAll('.decrement-btn');

        priceInputs.forEach(function(input) {
            input.addEventListener('input', updateTotals);
        });

        incrementButtons.forEach(function(button) {
            button.addEventListener('click', function() {
                var lineId = this.dataset.lineId;
                var input = document.getElementById('price_input_' + lineId);
                var currentValue = parseFloat(input.value) || 0;
                input.value = (currentValue + 1).toFixed(2);
                updateTotals();
            });
        });

        decrementButtons.forEach(function(button) {
            button.addEventListener('click', function() {
                var lineId = this.dataset.lineId;
                var input = document.getElementById('price_input_' + lineId);
                var currentValue = parseFloat(input.value) || 0;
                if (currentValue > 0) {
                    input.value = (currentValue - 1).toFixed(2);
                    updateTotals();
                }
            });
        });


    // Sign wizard
    var myModalEl = document.getElementById('signWizard');
    var myModal = new bootstrap.Modal(myModalEl);
    document.getElementById('open-sign-wizard').addEventListener('click', function() {
        myModal.show();
        resizeCanvas();
    });

    var canvas = document.getElementById('signature_canvas');
    var signaturePad = new SignaturePad(canvas, {
        backgroundColor: 'rgb(255, 255, 255)',
        penColor: 'rgb(0, 0, 0)'
    });

    function resizeCanvas() {
        var ratio = Math.max(window.devicePixelRatio || 1, 1);
        canvas.width = canvas.offsetWidth * ratio;
        canvas.height = canvas.offsetHeight * ratio;
        canvas.getContext('2d').scale(ratio, ratio);
        signaturePad.clear();
    }

    window.addEventListener('resize', resizeCanvas);
    document.getElementById('signWizard').addEventListener('shown.bs.modal', resizeCanvas);
    myModalEl.addEventListener('shown.bs.modal', resizeCanvas);

    // for draw
    document.getElementById('draw_sig').addEventListener('click', function() {
        signaturePad.clear();
        canvas.style.cursor = 'crosshair';
    });

    // for auto
    document.getElementById('auto_sig').addEventListener('click', function() {
        var vendor_signed_by = document.getElementById('vendor_signed_by').value.trim();
        if (vendor_signed_by) {
            signaturePad.clear();
            var ctx = canvas.getContext('2d');
            ctx.font = '40px "Cedarville Cursive"';
            ctx.fillStyle = 'rgb(0, 0, 0)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            var textWidth = ctx.measureText(vendor_signed_by).width;
            if (textWidth > canvas.width - 20) {
                ctx.font = '30px "Cedarville Cursive"';
            }
            ctx.fillText(vendor_signed_by, canvas.width / 2, canvas.height / 2);
            signaturePad.fromDataURL(canvas.toDataURL());
        } else {
            alert('Please enter your full name first.');
        }
    });

    // for load
    document.getElementById('load_sig_btn').addEventListener('click', function() {
        signaturePad.clear();
        document.getElementById('load_sig').click();
    });

    document.getElementById('load_sig').addEventListener('change', function (e) {
        var file = e.target.files[0];
        if (file) {
            var reader = new FileReader();
            reader.onload = function(event) {
                var img = new Image();
                img.onload = function() {
                    signaturePad.clear();
                    var ctx = canvas.getContext('2d');
                    var scale = Math.min(canvas.width / img.width, canvas.height / img.height);
                    var width = img.width * scale;
                    var height = img.height * scale;
                    ctx.clearRect(0, 0, canvas.width, canvas.height);
                    ctx.drawImage(img, (canvas.width - width) / 2, (canvas.height - height) / 2, width, height);
                    signaturePad.fromDataURL(canvas.toDataURL());
                };
                img.src = event.target.result;
            };
            reader.readAsDataURL(file);
        }
    });

    // for accept
    document.getElementById('acceptSign').addEventListener('click', function() {
        var vendor_signed_by = document.getElementById('vendor_signed_by').value;
        var vendor_signature = signaturePad.toDataURL('image/png');
        var orderId = document.getElementById('order_id').value;
        var updatedPrices = {};

        priceInputs.forEach(function(input) {
            if (input.value) {
                updatedPrices[input.dataset.lineId] = parseFloat(input.value) || '';
            }
        });

        var vendor_signed_on = new Date().toISOString();

        console.log('Order ID:', orderId);
        console.log('Updated Prices:', updatedPrices);
        console.log('Signed By:', vendor_signed_by);
        console.log('Signature Empty?', signaturePad.isEmpty());
        console.log('Signature Empty?', vendor_signed_on);
        var payload = {
            order_id: orderId,
            updated_prices: updatedPrices,
            vendor_signed_by: vendor_signed_by,
            vendor_signature: vendor_signature,
            vendor_signed_on: vendor_signed_on
        };
        console.log('Full payload:', payload);

        if (vendor_signed_by && !signaturePad.isEmpty()) {
            $.ajax({
                url: '/purchase/rfq/sign',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify(payload),
                success: function(result) {
                    console.log('Full server response:', result);
                    if (result.success) {
                        alert('Quotation sent successfully!');
                        var modalEl = document.getElementById('signWizard');
                        var modal = bootstrap.Modal.getInstance(modalEl);
                        if (modal) {
                            modal.hide();
                        }
                        document.getElementById('quotationForm').reset();
                        signaturePad.clear();

                        window.location.reload();

                        document.querySelectorAll('.price-unit-input').forEach(input => input.disabled = true);
                        document.querySelectorAll('.increment-btn, .decrement-btn').forEach(btn => btn.disabled = true);
                        document.getElementById('open-sign-wizard').disabled = true;
                    } else {
                        alert('Error sending quotation: ' + (result.error || 'Unknown error'));
                    }
                },
                error: function() {
                    alert('Error sending quotation.');
                }
            });
        } else {
            alert('Please fill in your full name and provide a signature.');
        }
    });

    updateTotals();
})();
